package net.civeira.phylax.features.access.userconsentedscopes.domain.valueobject;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.access.userconsentedscopes.domain.UserConsentedScopes;

@RequiredArgsConstructor
public class GrantedValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<GrantedVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<Boolean> getGranted() {
    return value.map(GrantedVO::isGranted);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<GrantedVO> getGrantedValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param granted
   * @return
   */
  public T granted(GrantedVO granted) {
    this.value = Optional.of(granted);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param granted
   * @return
   */
  public T granted(Optional<GrantedVO> granted) {
    this.value = granted;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param granted
   * @return
   */
  public T granted(Boolean granted) {
    this.value = Optional.of(GrantedVO.from(granted));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T grantedNull() {
    this.value = Optional.empty();
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public GrantedVO readGranted(final Optional<UserConsentedScopes> original,
      final ConstraintFailList fails) {
    return value
        .orElse(original.map(UserConsentedScopes::getGrantedValue).orElseGet(GrantedVO::nullValue));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetGranted() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetGrantedIfMatches(final String field) {
    if ("granted".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
